export function getBlogPosts(locale: AppLocale = 'pt-PT') {
  const forLocale = blogPosts
    .filter((p) => p.locales.includes(locale) && p.slugs[locale] && p.title[locale])
    .sort((a, b) => b.publishedAt.localeCompare(a.publishedAt))
  const source =
    forLocale.length > 0
      ? forLocale
      : // Editorial source is Portuguese — show PT articles on other locales until bodies are translated
        blogPosts
          .filter((p) => p.locales.includes('pt-PT') && p.slugs['pt-PT'] && p.title['pt-PT'])
          .sort((a, b) => b.publishedAt.localeCompare(a.publishedAt))
  return source.map((p) => localizeBlogPostFields(p, locale))
}

export function getBlogPostBySlug(locale: AppLocale, slug: string) {
  const fromList = getBlogPosts(locale).find(
    (p) => p.slugs[locale] === slug || p.slugs['pt-PT'] === slug,
  )
  if (fromList) return fromList
  const raw = blogPosts.find((p) => p.slugs['pt-PT'] === slug)
  return raw ? localizeBlogPostFields(raw, locale) : undefined
}

export function getBlogCategories(locale: AppLocale = 'pt-PT') {
  const set = new Set<string>()
  for (const p of getBlogPosts(locale)) p.categories.forEach((c) => set.add(c))
  return [...set].sort()
}
